import os
import re

def search_ascii_sequences(folder_path):
    flag_pattern = re.compile(r'flag\{.*?\}')
    findings = []

    for file_name in os.listdir(folder_path):
        if file_name.endswith('_binary.txt'):
            file_path = os.path.join(folder_path, file_name)
            with open(file_path, 'r') as f:
                binary_data = f.read()

            # Convert binary data to ASCII characters
            ascii_data = ''.join(chr(int(binary_data[i:i+8], 2)) for i in range(0, len(binary_data), 8))

            # Search for flag-like patterns
            match = flag_pattern.search(ascii_data)
            if match:
                findings.append((file_name, match.group()))

    return findings

# Set folder with extracted binary data
binary_folder = '/home/ctfplayer/ctf_files/extracted_data/'
if os.path.exists(binary_folder):
    results = search_ascii_sequences(binary_folder)

    if results:
        for file_name, flag in results:
            print(f"Found flag in {file_name}: {flag}")
    else:
        print("No flag-like patterns found.")
else:
    print(f"Binary folder {binary_folder} does not exist.")

